namespace sv_f8b5d1df5e9048bf90362ffd686342fd.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per circuit.
/// Components subscribe to <see cref="OnChange"/> to react when new data arrives.
/// </summary>
public class InventoryAlertService
{
    private static readonly Random _rng = new();

    public int LatestLowStockCount { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock.
    /// Stores the result and notifies all subscribers.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        int count;
        lock (_rng)
        {
            count = _rng.Next(0, 16);
        }

        LatestLowStockCount = count;
        OnChange?.Invoke();
        return Task.FromResult(count);
    }
}

