@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_f8b5d1df5e9048bf90362ffd686342fd.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p>Currently viewing: <strong>@Warehouse?.WarehouseName</strong></p>

<div class="card mt-3" style="max-width: 24rem;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text display-6">
            <span class="badge @BadgeClass">@_lowStockCount</span>
            <span class="fs-6 text-muted ms-2">items below minimum</span>
        </p>
        <p class="text-muted mb-0"><small>Refreshes every 10 seconds</small></p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private int _lowStockCount;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _handler;

    private string BadgeClass => _lowStockCount > 0 ? "bg-danger" : "bg-success";

    protected override void OnInitialized()
    {
        // Subscribe to alert changes triggered by our own polling —
        // this ensures the page-level count stays in sync with the
        // sidebar AlertBadge (requirement #3).
        _handler = () => InvokeAsync(() =>
        {
            _lowStockCount = AlertService.LatestLowStockCount;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        // Restart polling whenever the warehouse changes.
        await StopPollingAsync();
        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        if (Warehouse is null) return;

        // Fetch immediately so the UI isn't blank until the first tick.
        _lowStockCount = await AlertService.GetLowStockCountAsync(Warehouse.WarehouseId);

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                if (Warehouse is not null)
                {
                    await AlertService.GetLowStockCountAsync(Warehouse.WarehouseId);
                    // OnChange handler above picks up the new count.
                }
            }
        }
        catch (OperationCanceledException) { /* expected on dispose */ }
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

